<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue';
import {api,readLocal,writeLocal} from '../../platform';
import type {Guide} from '../../../packages/domain/catalog';
const uniApi=uni;
const tab=ref('发现'),meta=ref<any>(null),items=ref<Guide[]>([]),total=ref(0),next=ref<number|null>(null),detail=ref<Guide|null>(null),busy=ref(false),error=ref(''),user=ref<any>(null),consent=ref(false),saved=ref<Record<string,any>>(readLocal('saved',{})),actions=ref<Record<string,any>>(readLocal('actions',{})),listItems=ref<Guide[]>([]),note=ref('');
const q=reactive<Record<string,string>>({q:'',outcome:'',chapter:'',evidenceGrade:'',roi:'',money:'',time:'',effort:'',audience:'',controversy:'',needsVerification:'',sort:'chapter'});
const fields=[{key:'chapter',label:'章节'},{key:'evidenceGrade',label:'证据'},{key:'roi',label:'性价比'},{key:'money',label:'钱成本'},{key:'time',label:'时间'},{key:'effort',label:'毅力'},{key:'audience',label:'人群'},{key:'sort',label:'排序'}];
function options(key:string):string[]{return key==='chapter'?['全部',...(meta.value?.chapters??[]).map((c:any)=>`${c.id}. ${c.title}`)]:key==='sort'?['章节顺序',...(q.outcome?['性价比优先']:[]),'证据优先']:['不限',...({evidenceGrade:['A','B','C'],roi:['极高','高','一般'],money:['0','少','多'],time:['少','中','多'],effort:['否','些','是'],audience:meta.value?.audiences??[]} as any)[key]];}
function pick(key:string,e:any){const value=options(key)[Number(e.detail.value)];q[key]=key==='chapter'?(value==='全部'?'':value.split('.')[0]):key==='sort'?({'章节顺序':'chapter','性价比优先':'roi','证据优先':'evidence'} as any)[value]:value==='不限'?'':value;void load();}
function label(key:string){if(key==='chapter')return meta.value?.chapters.find((c:any)=>c.id===q.chapter)?.title??'全部';if(key==='sort')return ({chapter:'章节顺序',roi:'性价比优先',evidence:'证据优先'} as any)[q.sort];return q[key]||'不限';}
async function run(fn:()=>Promise<void>){error.value='';try{await fn();}catch(e){error.value=(e as Error).message;}}
async function load(append=false){busy.value=true;await run(async()=>{const params=Object.entries(q).filter(([,v])=>v).map(([k,v])=>`${k}=${encodeURIComponent(v)}`);params.push(`offset=${append?next.value??0:0}`);const r=await api('/guides?'+params.join('&'));items.value=append?[...items.value,...r.items]:r.items;total.value=r.total;next.value=r.nextOffset;});busy.value=false;}
function outcome(value:string){q.outcome=value;if(!value)q.sort='chapter';else q.sort='roi';tab.value='指南库';void load();}
function reset(){for(const k in q)q[k]=k==='sort'?'chapter':'';void load();}
async function open(g:Guide){await run(async()=>{detail.value=await api('/guides/'+g.id);note.value=actions.value[g.id]?.note??'';uni.setStorageSync('last-guide',g.id);});}
async function refreshLists(){if(user.value){saved.value=await api('/me/saved');actions.value=await api('/me/actions');}const ids=[...new Set([...Object.keys(saved.value),...Object.keys(actions.value)])];listItems.value=await Promise.all(ids.map(id=>api('/guides/'+id).catch(()=>null))).then(rows=>rows.filter(Boolean));}
async function change(kind:'saved'|'actions',g:Guide,value:any){await run(async()=>{const target=kind==='saved'?saved:actions;if(user.value)await api(`/me/${kind}/${g.id}`,value?'PUT':'DELETE',value||undefined);if(value)target.value[g.id]=value;else delete target.value[g.id];if(!user.value)writeLocal(kind,target.value);await refreshLists();});}
async function navigate(value:string){tab.value=value;detail.value=null;if(value==='我的清单')await run(refreshLists);}
async function login(){if(!consent.value){error.value='请先阅读并同意隐私说明';return;}await run(async()=>{user.value=await api('/auth/dev','POST',{consent:true});const r=await api('/me/merge-local','POST',{saved:readLocal('saved',{}),actions:readLocal('actions',{})});await refreshLists();if(r.conflicts.length)error.value='部分条目已有云端记录，已保留云端版本，本地原记录仍保留。';});}
async function logout(){await run(async()=>{await api('/auth/session','DELETE');user.value=null;saved.value=readLocal('saved',{});actions.value=readLocal('actions',{});await refreshLists();});}
async function removeAccount(){uni.showModal({title:'注销账号',content:'删除此开发账号及服务器收藏、行动记录。访客本地记录保留。',success:async r=>{if(r.confirm)await run(async()=>{await api('/me','DELETE');user.value=null;saved.value=readLocal('saved',{});actions.value=readLocal('actions',{});});}});}
async function exportData(){await run(async()=>{const data=user.value?await api('/me/export'):{saved:saved.value,actions:actions.value};uni.setClipboardData({data:JSON.stringify(data,null,2)});});}
function source(g:Guide){uni.setClipboardData({data:`https://github.com/eternity4719/HowToLiveBetter/blob/${g.sourceCommit}/${g.sourcePath}`});}
onMounted(async()=>{await run(async()=>{meta.value=await api('/catalog/meta');try{user.value=await api('/me');await refreshLists();}catch{user.value=null;}});await load();});
</script>
<template>
<view class="shell">
 <view class="header"><text class="brand">✳ 高性价比人生赢家</text><button class="small" @click="navigate('我的')">{{user?'我的账号':'访客 / 登录'}}</button></view>
 <view v-if="error" class="error" role="alert">{{error}} <button class="small" @click="load()">重试</button></view>
 <view v-if="detail" class="detail">
  <button class="small" @click="detail=null">← 返回列表</button><view class="muted">第 {{detail.chapterId}} 节 · 第 {{detail.itemNumber}} 条</view><view class="title">{{detail.title}}</view>
  <view class="tags"><text>{{detail.roi}}</text><text>证据 {{detail.evidenceGrade}}</text><text v-if="detail.controversy">有争议</text><text v-if="detail.needsVerification">待核实</text></view>
  <view v-for="section in [{label:'说人话',text:detail.plainText},{label:'成本',text:detail.costText},{label:'完整收益与研究条件',text:detail.benefitText},{label:'适用与限制 / 备注',text:detail.notes},{label:'原始来源',text:detail.sourceText}]" :key="section.label" class="detail-section"><view class="subtitle">{{section.label}}</view><text selectable class="prose">{{section.text||'未标注'}}</text></view>
  <view class="muted">人群条件：{{detail.audienceGroups.length?detail.audienceGroups.map(g=>g.join(' 且 ')).join(' 或 '):'未标注，请以正文为准'}}</view>
<button class="small" @click="source(detail)">复制固定版本原文链接</button><view v-for="link in detail.links" :key="link" class="source-link" @click="uniApi.setClipboardData({data:link})">{{link}} · 复制</view>
  <view class="tools"><button @click="change('saved',detail,saved[detail.id]?null:{saved:true})">{{saved[detail.id]?'取消收藏':'☆ 收藏'}}</button><picker :range="['准备做','进行中','已完成','暂不适用','移出行动']" @change="(e:any)=>change('actions',detail!,Number(e.detail.value)===4?null:{status:['准备做','进行中','已完成','暂不适用'][Number(e.detail.value)],note})"><view class="action-button">{{actions[detail.id]?.status||'加入行动清单'}} ▾</view></picker></view>
  <textarea v-model="note" maxlength="2000" placeholder="我的备注（可选，最多 2000 字）" class="note"/><button class="small" @click="change('actions',detail,{status:actions[detail.id]?.status||'准备做',note})">保存备注</button>
 </view>
 <template v-else-if="tab==='发现'||tab==='指南库'">
  <view v-if="tab==='发现'" class="hero"><view><view class="eyebrow">A LITTLE BETTER, EVERY DAY</view><view class="hero-title">把有限的精力，<br/>花在值得的地方。</view><view class="muted">有出处、能筛选、可行动。先查清楚，再选适合自己的那一件。</view><view class="stats">{{meta?.chapters.length??'—'}} 个章节 · {{meta?.total??'—'}} 条真实建议</view></view><view class="quote"><view class="muted">给今天的你</view><view class="subtitle">不用全做。<br/>挑走一两条，就算数。</view><text>从自己的生活开始，不必和别人比赛。</text></view></view>
  <view class="search"><input v-model="q.q" placeholder="搜索生活问题，例如租房、戒烟、账号安全" confirm-type="search" @confirm="load()"/><button class="small" @click="load()">搜索</button></view>
<view class="categories"><button :class="{active:!q.outcome}" @click="outcome('')">全部指南</button><button v-for="(name,key) in meta?.outcomes" :key="key" :class="{active:q.outcome===String(key)}" @click="outcome(String(key))">{{name}}</button></view>
  <view class="section"><view class="subtitle">{{q.outcome?meta?.outcomes[q.outcome]:'生活指南库'}}</view><button class="small" @click="reset">重置筛选</button></view>
  <view class="filters"><picker v-for="f in fields" :key="f.key" :range="options(f.key)" @change="pick(f.key,$event)"><view class="filter">{{f.label}}：{{label(f.key)}} ▾</view></picker></view>
  <view class="filters"><button class="small" :class="{active:q.controversy}" @click="q.controversy=q.controversy?'':'1';load()">只看争议</button><button class="small" :class="{active:q.needsVerification}" @click="q.needsVerification=q.needsVerification?'':'1';load()">待核实</button><button class="small" @click="q.chapter='13';q.outcome='';q.sort='chapter';q.q='';load()">应急：第 13 节</button></view>
  <view class="muted explanation">{{q.sort==='roi'?'同口径内按性价比档、钱、时间、毅力及章节排序。档位是作者判断，不是研究证据。':q.sort==='evidence'?'按 A/B/C 及章节排序。A 级不意味着一定存在因果关系。':'按章节与条目顺序。选择一种收益口径后，可按性价比排序。'}} · {{total}} 条结果</view>
  <view v-if="busy" class="empty">正在加载…</view><view v-else-if="!items.length" class="empty">没有符合条件的条目，试试减少筛选条件。</view>
  <view class="grid"><view v-for="g in items" :key="g.id" class="card"><view class="tags"><text>{{g.roi}}</text><text>证据 {{g.evidenceGrade}}</text><text v-if="g.controversy">争议</text></view><button class="card-title" @click="open(g)">{{g.title}}</button><view class="summary">{{g.plainText}}</view><view class="cost">钱：{{g.money||'未标注'}}　时间：{{g.time||'未标注'}}　毅力：{{g.effort||'未标注'}}</view><view class="card-footer"><text class="muted">第 {{g.chapterId}} 节 · 第 {{g.itemNumber}} 条</text><button class="small" @click="change('saved',g,saved[g.id]?null:{saved:true})">{{saved[g.id]?'★ 已收藏':'☆ 收藏'}}</button></view></view></view>
  <button v-if="next!==null" class="more" :disabled="busy" @click="load(true)">加载更多</button>
 </template>
 <view v-else-if="tab==='我的清单'"><view class="title">我的清单</view><view class="muted">{{user?'已登录，记录保存在本地服务器。':'访客记录仅保存在此设备。登录后可合并。'}}</view><view v-if="!listItems.length" class="empty">从指南里收藏一条，或加入行动清单。</view><view v-for="g in listItems" :key="g.id" class="card"><button class="card-title" @click="open(g)">{{g.title}}</button><view class="tags"><text v-if="saved[g.id]">已收藏</text><text v-if="actions[g.id]">{{actions[g.id].status}}</text></view><text>{{actions[g.id]?.note}}</text></view></view>
 <view v-else class="profile"><view class="title">我的生活工具箱</view><view class="card"><view class="subtitle">{{user?'本地开发账号':'游客也能自由查阅'}}</view><view class="muted">{{user?'会话有效期 7 天。此账号仅用于本机调试。':'浏览无需登录，收藏可先保存在当前设备。'}}</view><template v-if="!user"><view class="privacy">隐私说明：模拟登录会创建随机开发账号；服务器保存收藏、行动状态及你主动填写的备注，不收集手机号、病史或位置。账号可导出、注销。访客数据保存在当前设备。</view><checkbox-group @change="(e:any)=>consent=e.detail.value.includes('yes')"><label><checkbox value="yes" :checked="consent"/>我已阅读并同意以上隐私说明</label></checkbox-group><button v-if="meta?.devAuth" class="primary" @click="login">开发登录并合并访客记录</button><view v-else class="muted">微信登录将在小程序适配阶段开放。</view></template><template v-else><button @click="logout">退出登录</button><button @click="removeAccount">注销开发账号</button></template><button @click="exportData">复制我的数据（JSON 导出）</button></view><view class="card"><view class="subtitle">知识库与许可</view><text class="prose">内容来自《高性价比人生指南》/ eternity4719，采用 CC BY 4.0。原文内容保留，列表是节选展示。政策和研究可能更新，请结合当地实际与专业建议。
证据 A：可核对数字及原始研究或官方文件；B：研究支持但有限；C：经验或公认做法。证据等级与性价比相互独立。
当前版本：{{meta?.sourceCommit}}
导入时间：{{meta?.importedAt}}</text><button class="small" @click="uniApi.setClipboardData({data:'https://github.com/eternity4719/HowToLiveBetter'})">复制知识库链接</button><button class="small" @click="uniApi.setClipboardData({data:'https://creativecommons.org/licenses/by/4.0/'})">复制许可链接</button></view></view>
 <view class="attribution">来源：高性价比人生指南 · eternity4719 · CC BY 4.0<br/>性价比是判断，证据不是承诺。查看详情以核对原文限制和出处。</view>
 <view class="nav"><button v-for="t in ['发现','指南库','我的清单','我的']" :key="t" :class="{selected:tab===t}" @click="navigate(t)">{{t}}</button></view>
</view>
</template>
<style scoped>
.shell{max-width:1040px;margin:auto;padding:24px 24px 100px;font-size:15px;line-height:1.7}.header,.section,.card-footer,.tools{display:flex;align-items:center;justify-content:space-between;gap:12px}.header{padding-bottom:22px;border-bottom:1px solid #e3e6db}.brand{font-weight:750;font-size:20px;color:#214d3f}.small{margin:0;padding:3px 13px;border:1px solid #dfe4d7;border-radius:20px;color:#214d3f;background:#fffdf6;font-size:12px;line-height:32px}.hero{display:grid;grid-template-columns:1.7fr 1fr;gap:40px;padding:38px 0}.eyebrow{font-size:12px;letter-spacing:3px;color:#44745b}.hero-title{font-size:42px;line-height:1.35;font-weight:750;letter-spacing:-1px;margin:14px 0}.muted,.stats{color:#727b72;font-size:13px}.stats{margin-top:15px}.quote{background:#e7eddf;border-radius:20px;padding:26px;display:flex;flex-direction:column;justify-content:center;font-size:13px;gap:12px}.subtitle{font-size:21px;font-weight:650;line-height:1.6}.search{display:flex;background:white;border:1px solid #e3e6db;border-radius:14px;padding:13px 16px;align-items:center;margin:23px 0}.search input{flex:1;min-width:0;font-size:14px}.categories{display:flex;gap:10px;flex-wrap:wrap}.categories button{flex:1;min-width:110px;margin:0;border-radius:13px;background:white;color:#214d3f;border:1px solid #e3e6db;font-size:15px;padding:6px}.categories .active,.active{background:#214d3f!important;color:white!important}.section{margin:26px 0 15px}.filters{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.filter{background:#e7eddf;color:#214d3f;border-radius:8px;font-size:12px;padding:9px 12px;max-width:280px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.explanation{margin:15px 0 20px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.card{background:white;border:1px solid #e3e6db;border-radius:18px;padding:23px;margin-bottom:12px;min-width:0}.tags{display:flex;gap:8px;flex-wrap:wrap}.tags text{background:#eef3e8;color:#477347;border-radius:6px;font-size:12px;padding:3px 9px}.tags text:nth-child(2){background:#faf0d9;color:#956e27}.card-title{font-size:19px;font-weight:650;line-height:1.5;padding:0;margin:14px 0 10px;text-align:left;background:transparent;overflow-wrap:anywhere}.summary{color:#727b72;font-size:14px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;min-height:72px}.cost{border-top:1px solid #e3e6db;padding-top:12px;margin-top:15px;font-size:13px}.card-footer{margin-top:12px}.nav{position:fixed;bottom:0;left:0;right:0;background:#fffef8;border-top:1px solid #e3e6db;padding:12px max(10px,calc((100vw - 1040px)/2));display:flex;z-index:5;padding-bottom:calc(12px + env(safe-area-inset-bottom))}.nav button{flex:1;margin:0;background:transparent;font-size:13px;color:#727b72;line-height:35px}.nav .selected{color:#214d3f;font-weight:750}.attribution{font-size:12px;color:#727b72;margin:30px 0;line-height:1.8}.empty{text-align:center;padding:45px 15px;color:#727b72}.title{font-size:28px;font-weight:700;margin:24px 0 18px}.detail-section{margin:25px 0;padding-bottom:20px;border-bottom:1px solid #e3e6db}.prose{white-space:pre-wrap;overflow-wrap:anywhere;display:block;font-size:15px;line-height:1.9}.detail .subtitle{margin-bottom:12px}.source-link{overflow-wrap:anywhere;color:#477347;font-size:12px;margin:12px 0;cursor:pointer}.tools{justify-content:flex-start;flex-wrap:wrap;margin:25px 0}.tools button,.action-button{background:#e7eddf;padding:10px 20px;border-radius:12px;margin:0;color:#214d3f;font-size:14px;line-height:28px}.note{background:white;border:1px solid #e3e6db;padding:15px;width:100%;box-sizing:border-box;border-radius:12px;height:130px}.privacy{margin:20px 0;font-size:14px;color:#727b72}.profile button{margin-top:15px}.primary{background:#214d3f;color:white}.error{background:#ffe7dd;color:#863f2d;padding:14px;border-radius:12px;margin-top:15px}.more{background:white;margin-top:20px;color:#214d3f}@media(max-width:650px){.shell{padding:18px 18px 100px}.brand{font-size:16px}.hero{grid-template-columns:1fr;gap:20px;padding:25px 0}.hero-title{font-size:33px}.quote{padding:20px}.grid{grid-template-columns:1fr}.categories button{min-width:95px;font-size:13px}.title{font-size:23px}.header{gap:8px}.small{padding:2px 10px}.card{padding:19px}.filter{max-width:230px}}
</style>
